const data = $input.first().json.body || $input.first().json;

// Поля из формы Tilda (реальные имена полей)
const email = (data.Email || data.EMAIL || data.email || '').trim();
const name = (data.Name || data.NAME || data.name || '').trim();
const phone = (data.Phone || data.PHONE || data.phone || '').trim();
const delivery = (data['Доставка_самовывоз'] || data['ДОСТАВКА__САМОВЫВОЗ'] || '').trim();
const deliveryDate = (data['Дата_доставки_самовывоза'] || data['ДАТА_ДОСТАВКИ__САМОВЫВОЗА'] || '').trim();
const deliveryTime = (data['Время_доставки_самовывоза'] || data['ВРЕМЯ_ДОСТАВКИ__САМОВЫВОЗА'] || '').trim();
const name2 = (data.Name_2 || data.NAME_2 || '').trim();
const phone2 = (data.Phone_2 || data.PHONE_2 || '').trim();

// Данные заказа (Tilda передаёт через payment[...])
const orderNum = data['payment[orderid]'] || '—';
const orderName = data['payment[products][0][name]'] || 'не указан';
const orderSum = data['payment[amount]'] || data['payment[subtotal]'] || '0';
const paymentType = data.paymentsystem || data['payment[system]'] || 'не указан';
const paymentStatus = 'Ожидает оплаты';

// Оценка заполненности
const missing = [];
if (!email) missing.push('Email');
if (!name) missing.push('Имя клиента');
if (!phone) missing.push('Телефон клиента');
if (!delivery) missing.push('Адрес/способ доставки');
if (!deliveryDate) missing.push('Дата доставки');
if (!deliveryTime) missing.push('Время доставки');

let status;
if (missing.length >= 3) {
  status = 'critical';
} else if (missing.length > 0) {
  status = 'partial';
} else {
  status = 'full';
}

const score = Math.round(((6 - missing.length) / 6) * 100);

return [{
  json: {
    status,
    score,
    missing,
    fields: { email, name, phone, delivery, deliveryDate, deliveryTime, name2, phone2 },
    order: { orderNum, orderName, orderSum, paymentStatus, paymentType }
  }
}];

